#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

long long maxProductSubarray(int arr[], int n) {
    if (n == 0) return 0;

    long long max_prod = arr[0];
    long long min_prod = arr[0];
    long long result = arr[0];

    for (int i = 1; i < n; i++) {
        long long temp_max = max_prod;
        max_prod = fmax(arr[i], fmax(max_prod * arr[i], min_prod * arr[i]));
        min_prod = fmin(arr[i], fmin(temp_max * arr[i], min_prod * arr[i]));

        result = fmax(result, max_prod);
    }

    return result;
}

void getInputArray(int arr[], int n) {
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("-1\n");
        return 0;
    }

    int *arr = (int *)malloc(n * sizeof(int));
    if (arr == NULL) {
        printf("-1\n");
        return 0;
    }

    getInputArray(arr, n);

    long long result = maxProductSubarray(arr, n);
    printf("%lld\n", result);

    free(arr);
    return 0;
}
